1	package clinical
2	
3	import (
4		"crypto/sha256"
5		"encoding/hex"
6		"encoding/json"
7		"fmt"
8		"sort"
9		"strings"
10		"time"
11	)
12	
13	// PackageDelivery 是指定接收方取包时得到的视图：交换标识、当前状态、
14	// 创建时间、包内容与摘要，不含内部使用者标识等包外信息。
15	type PackageDelivery struct {
16		ExchangeID ID
17		Status     string
18		Digest     string
19		CreatedAt  time.Time
20		Package    Package
21	}
22	
23	// ReceiptConfirmation 是接收方登记回执后得到的确认。
24	// 只含交换标识、当前状态、回执结果与登记时间，不含任何受保护内容；
25	// 授权失效或患者停用后登记回执也只返回该确认。
26	type ReceiptConfirmation struct {
27		ExchangeID   ID
28		Status       string
29		Outcome      string
30		RegisteredAt time.Time
31	}
32	
33	// CreateExchange 由内部使用者把一条当前有效授权覆盖的已生效记录集合打包给
34	// 指定接收方。
35	//
36	// 参数：患者、接收方、绑定授权、记录标识集合与非空请求号。记录必须属于该
37	// 患者且已经生效；每条记录都必须被绑定的那一条授权覆盖——整类范围按记录的
38	// 就诊+类别覆盖，限定范围只覆盖明确选中的记录，不能借用同一接收方的其他
39	// 授权补足。授权必须属于该患者与接收方且在当前时间有效。空集合、空白请求号、
40	// 不存在或跨患者的引用、夹带草稿、记录不被绑定授权覆盖、授权不符一律拒绝，
41	// 不留下交换或审计，也不占用请求号。患者停用后不能新建交换。
42	//
43	// 成功后包内容固化为创建时各记录的当前生效版本（重复记录标识合并），并计算
44	// 稳定摘要，状态为待回执；交换与审计事件在同一次原子落盘中保留。此后记录被
45	// 更正或有新版本、新增记录都不会改写已创建的包。
46	//
47	// 请求号按发起的内部使用者区分：同一使用者以相同请求号携带相同患者、接收方、
48	// 授权与记录集合（顺序不限）重试时，返回原交换及其现有状态，不重新取内容、
49	// 不新增审计；其他参数变化返回 ErrConflict。首次失败不占用请求号。
50	// 命中已保存交换的重试只是读取既有结果、不产生任何状态变更，因此不再落盘：
51	// 即使本地保存条件当前不可用，重试也成功返回正式保存的那份交换。
52	func (s *Store) CreateExchange(actor Actor, patientID ID, receiverID, authorizationID ID, recordIDs []ID, requestID string) (Exchange, error) {
53		if !actor.valid() || !actor.IsInternal() {
54			return Exchange{}, ErrAccessDenied
55		}
56		if patientID == "" {
57			return Exchange{}, fmt.Errorf("%w: patient id is required", ErrInvalidArgument)
58		}
59		if strings.TrimSpace(receiverID) == "" {
60			return Exchange{}, fmt.Errorf("%w: receiver id is required", ErrInvalidArgument)
61		}
62		if strings.TrimSpace(authorizationID) == "" {
63			return Exchange{}, fmt.Errorf("%w: authorization id is required", ErrInvalidArgument)
64		}
65		if strings.TrimSpace(requestID) == "" {
66			return Exchange{}, fmt.Errorf("%w: request id is required", ErrInvalidArgument)
67		}
68		if len(recordIDs) == 0 {
69			return Exchange{}, fmt.Errorf("%w: record id set must not be empty", ErrInvalidArgument)
70		}
71		for _, rid := range recordIDs {
72			if strings.TrimSpace(rid) == "" {
73				return Exchange{}, fmt.Errorf("%w: record id must not be blank", ErrInvalidArgument)
74			}
75		}
76		wanted := uniqueSortedIDs(recordIDs)
77	
78		var result Exchange
79		err := s.mutate(func(snap *snapshot) error {
80			// 幂等检索优先：同一使用者的同一请求号无论当前患者/授权状态如何，
81			// 都只返回原结果（重试不是新建）。
82			if existing := findExchangeByRequest(snap, actor.ID, requestID); existing != nil {
83				if !sameExchangeRequest(existing, patientID, receiverID, authorizationID, wanted) {
84					return fmt.Errorf("%w: request id %q already used with different parameters", ErrConflict, requestID)
85				}
86				result = *existing
87				if existing.Receipt != nil {
88					r := *existing.Receipt
89					result.Receipt = &r
90				}
91				result.Package.Records = append([]PackagedRecord(nil), existing.Package.Records...)
92				// 命中已保存的交换：没有任何状态变更，不落盘——即使本地保存
93				// 条件当前不可用，重试也必须成功返回原交换。
94				return errUnchanged
95			}
96	
97			// 首次创建：患者必须存在且未停用。
98			if _, err := requireActivePatient(snap, patientID); err != nil {
99				return err
100			}
101	
102			// 绑定授权必须存在、属于该患者与接收方、当前有效。
103			a := snap.Authorizations[authorizationID]
104			if a == nil {
105				return fmt.Errorf("%w: authorization %q", ErrNotFound, authorizationID)
106			}
107			if a.PatientID != patientID {
108				return fmt.Errorf("%w: authorization %q belongs to patient %q, not %q",
109					ErrMismatchedPatient, authorizationID, a.PatientID, patientID)
110			}
111			if a.ReceiverID != receiverID {
112				return fmt.Errorf("%w: authorization %q is bound to receiver %q, not %q",
113					ErrInvalidArgument, authorizationID, a.ReceiverID, receiverID)
114			}
115			now := s.now()
116			if !a.ActiveAt(now) {
117				// 未开始、已到期或已撤回：没有覆盖此次打包的有效授权。
118				return fmt.Errorf("%w: authorization %q is not active", ErrAccessDenied, authorizationID)
119			}
120	
121			// 逐记录固化当前生效版本；重复标识已合并，按记录标识排序保证确定性。
122			pkg := Package{PatientID: patientID, ReceiverID: receiverID}
123			for _, rid := range wanted {
124				r := snap.Records[rid]
125				if r == nil {
126					return fmt.Errorf("%w: record %q", ErrNotFound, rid)
127				}
128				if r.PatientID != patientID {
129					return fmt.Errorf("%w: record %q belongs to patient %q, not %q",
130						ErrMismatchedPatient, rid, r.PatientID, patientID)
131				}
132				if r.CurrentVersionID == "" {
133					return fmt.Errorf("%w: record %q has no effective version; activate its draft first",
134						ErrInvalidArgument, rid)
135				}
136				v := snap.Versions[r.CurrentVersionID]
137				if v == nil {
138					return fmt.Errorf("%w: current version %q of record %q", ErrNotFound, r.CurrentVersionID, rid)
139				}
140				// 每条记录都必须被绑定授权自身覆盖：整类范围或限定范围。
141				// 同一接收方的其他授权不能补足；夹带一条未覆盖记录即整包拒绝。
142				if !authorizationCoversRecord(a, r) {
143					return fmt.Errorf("%w: record %q (encounter %q, category %q) is not covered by authorization %q",
144						ErrAccessDenied, rid, r.EncounterID, r.Category, authorizationID)
145				}
146				pkg.Records = append(pkg.Records, PackagedRecord{
147					EncounterID: r.EncounterID,
148					Category:    r.Category,
149					RecordID:    r.ID,
150					VersionID:   v.ID,
151					Version:     v.Number,
152					EffectiveAt: v.CreatedAt,
153					Content:     v.Content,
154				})
155			}
156	
157			x := &Exchange{
158				ID:              newID("exch"),
159				PatientID:       patientID,
160				ReceiverID:      receiverID,
161				AuthorizationID: authorizationID,
162				RequestID:       requestID,
163				CreatorID:       actor.ID,
164				Status:          ExchangePending,
165				Digest:          packageDigest(pkg),
166				Package:         pkg,
167				CreatedAt:       now,
168			}
169			snap.Exchanges[x.ID] = x
170			s.addAudit(snap, patientID, actor, ActionExchanged, "exchange", x.ID, now)
171			result = *x
172			result.Package.Records = append([]PackagedRecord(nil), x.Package.Records...)
173			return nil
174		})
175		return result, err
176	}
177	
178	// FetchPackage 供指定接收方凭交换标识取包。
179	//
180	// 每次取包都重新检查绑定授权与患者状态：授权必须仍是创建时绑定的那一条且
181	// 已开始、未到期、未撤回，患者档案必须未停用；其他有效授权不能替代绑定授权。
182	// 是否允许取包按“本次核对时间”判断：请求发出后若因等待同一存储上的其他操作
183	// 而排队，以等待结束、真正开始核对本次取包权限的时刻为准（进入临界区后才
184	// 取样，与接收方 Read 的时间含义一致），提前发出的请求不会延长授权有效期；
185	// 时间窗仍是半开区间 [开始, 截止)，恰好到达截止时刻即失效。授权未开始、
186	// 到期、撤回或患者停用后返回 ErrAccessDenied，交付结果为空，不返回包内容、
187	// 摘要、记录标识或交换状态。
188	// 其他接收方、内部使用者以及不存在的交换统一拒绝，不泄露交换是否存在。
189	//
190	// 成功时返回交换创建时固化的包及其摘要与当前状态；此后记录被更正也不会
191	// 重新打包，包内版本与内容仍以创建时保存的为准。
192	func (s *Store) FetchPackage(actor Actor, exchangeID ID) (PackageDelivery, error) {
193		if !actor.valid() || actor.Kind != "receiver" {
194			return PackageDelivery{}, ErrAccessDenied
195		}
196		if strings.TrimSpace(exchangeID) == "" {
197			return PackageDelivery{}, fmt.Errorf("%w: exchange id is required", ErrInvalidArgument)
198		}
199	
200		var out PackageDelivery
201		err := s.view(func(snap *snapshot) error {
202			// 核对时刻在进入临界区、真正开始核对本次取包权限时才取样：请求发出后
203			// 若因等待其他操作而排队，等待时间不能延长绑定授权的有效判断——
204			// 是否可取一律按这同一时刻判断，与 Read 的时间含义一致。
205			now := s.now()
206			x := snap.Exchanges[exchangeID]
207			if x == nil || x.ReceiverID != actor.ID {
208				// 不存在或属于其他接收方：统一拒绝，不泄露存在性。
209				return ErrAccessDenied
210			}
211			p := snap.Patients[x.PatientID]
212			if p == nil || p.Deactivated {
213				return ErrAccessDenied
214			}
215			// 必须仍是绑定的那条授权（同一患者与接收方）；其他有效授权不能替代。
216			a := snap.Authorizations[x.AuthorizationID]
217			if a == nil || a.PatientID != x.PatientID || a.ReceiverID != actor.ID || !a.ActiveAt(now) {
218				return ErrAccessDenied
219			}
220			out = PackageDelivery{
221				ExchangeID: x.ID,
222				Status:     x.Status,
223				Digest:     x.Digest,
224				CreatedAt:  x.CreatedAt,
225				Package:    clonePackage(x.Package),
226			}
227			return nil
228		})
229		return out, err
230	}
231	
232	// SubmitReceipt 供指定接收方对一份包登记回执：提供交换标识、取包时得到的
233	// 包摘要、接受或拒绝的结果及原因。
234	//
235	// 非法结果、拒绝时原因为空白返回 ErrInvalidArgument。只有指定接收方且摘要
236	// 吻合，才能把交换从待回执变为已接受或已拒绝；摘要不符返回 ErrConflict，
237	// 状态不变。相同回执（结果与原因均相同）重交返回原确认，不新增审计；结果
238	// 或原因改变返回 ErrConflict。其他身份不能代交，不存在的交换统一拒绝。
239	//
240	// 授权失效或患者停用后仍允许登记此前包的回执，但响应只返回确认状态，
241	// 不提供任何受保护内容。
242	func (s *Store) SubmitReceipt(actor Actor, exchangeID ID, digest, outcome, reason string) (ReceiptConfirmation, error) {
243		if !actor.valid() || actor.Kind != "receiver" {
244			return ReceiptConfirmation{}, ErrAccessDenied
245		}
246		if strings.TrimSpace(exchangeID) == "" {
247			return ReceiptConfirmation{}, fmt.Errorf("%w: exchange id is required", ErrInvalidArgument)
248		}
249		if outcome != ReceiptAccepted && outcome != ReceiptRejected {
250			return ReceiptConfirmation{}, fmt.Errorf("%w: outcome must be %q or %q", ErrInvalidArgument, ReceiptAccepted, ReceiptRejected)
251		}
252		if outcome == ReceiptRejected && strings.TrimSpace(reason) == "" {
253			return ReceiptConfirmation{}, fmt.Errorf("%w: rejection reason is required", ErrInvalidArgument)
254		}
255		if outcome == ReceiptAccepted {
256			// 接受不携带原因；统一归一化，保证重复提交判定稳定。
257			reason = ""
258		}
259	
260		var conf ReceiptConfirmation
261		err := s.mutate(func(snap *snapshot) error {
262			x := snap.Exchanges[exchangeID]
263			if x == nil || x.ReceiverID != actor.ID {
264				// 不存在或属于其他接收方/其他身份：统一拒绝。
265				return ErrAccessDenied
266			}
267			if digest != x.Digest {
268				return fmt.Errorf("%w: package digest does not match exchange %q", ErrConflict, exchangeID)
269			}
270			if x.Receipt != nil {
271				if x.Receipt.Outcome != outcome || x.Receipt.Reason != reason {
272					return fmt.Errorf("%w: exchange %q already has a different receipt", ErrConflict, exchangeID)
273				}
274				// 相同回执重交：返回原确认，不新增审计、不改状态。
275				conf = ReceiptConfirmation{
276					ExchangeID:   x.ID,
277					Status:       x.Status,
278					Outcome:      x.Receipt.Outcome,
279					RegisteredAt: x.Receipt.RegisteredAt,
280				}
281				return nil
282			}
283	
284			now := s.now()
285			x.Receipt = &Receipt{Outcome: outcome, Reason: reason, RegisteredAt: now}
286			if outcome == ReceiptAccepted {
287				x.Status = ExchangeAccepted
288			} else {
289				x.Status = ExchangeRejected
290			}
291			s.addAudit(snap, x.PatientID, actor, ActionReceipted, "exchange", x.ID, now)
292			conf = ReceiptConfirmation{
293				ExchangeID:   x.ID,
294				Status:       x.Status,
295				Outcome:      outcome,
296				RegisteredAt: now,
297			}
298			return nil
299		})
300		return conf, err
301	}
302	
303	// GetExchange 供内部使用者按患者查看原包（含固化内容与摘要）及回执。
304	// 患者停用后仍可查看。交换不存在返回 ErrNotFound，属于其他患者返回
305	// ErrMismatchedPatient。
306	func (s *Store) GetExchange(actor Actor, patientID, exchangeID ID) (Exchange, error) {
307		if !actor.valid() || !actor.IsInternal() {
308			return Exchange{}, ErrAccessDenied
309		}
310		var result Exchange
311		err := s.view(func(snap *snapshot) error {
312			x, err := requireExchange(snap, patientID, exchangeID)
313			if err != nil {
314				return err
315			}
316			result = cloneExchangeValue(x)
317			return nil
318		})
319		return result, err
320	}
321	
322	// ListExchanges 供内部使用者按患者查看其全部交换（原包与回执），
323	// 按创建时间旧到新排序；时间戳相同时按交换标识排序。患者停用后仍可查看。
324	func (s *Store) ListExchanges(actor Actor, patientID ID) ([]Exchange, error) {
325		if !actor.valid() || !actor.IsInternal() {
326			return nil, ErrAccessDenied
327		}
328		var result []Exchange
329		err := s.view(func(snap *snapshot) error {
330			if _, err := requirePatient(snap, patientID); err != nil {
331				return err
332			}
333			for _, x := range snap.Exchanges {
334				if x.PatientID == patientID {
335					result = append(result, cloneExchangeValue(x))
336				}
337			}
338			sort.Slice(result, func(i, j int) bool {
339				if !result[i].CreatedAt.Equal(result[j].CreatedAt) {
340					return result[i].CreatedAt.Before(result[j].CreatedAt)
341				}
342				return result[i].ID < result[j].ID
343			})
344			return nil
345		})
346		return result, err
347	}
348	
349	func requireExchange(snap *snapshot, patientID, exchangeID ID) (*Exchange, error) {
350		x := snap.Exchanges[exchangeID]
351		if x == nil {
352			return nil, fmt.Errorf("%w: exchange %q", ErrNotFound, exchangeID)
353		}
354		if x.PatientID != patientID {
355			return nil, fmt.Errorf("%w: exchange %q belongs to patient %q, not %q",
356				ErrMismatchedPatient, exchangeID, x.PatientID, patientID)
357		}
358		return x, nil
359	}
360	
361	func findExchangeByRequest(snap *snapshot, creatorID, requestID string) *Exchange {
362		for _, x := range snap.Exchanges {
363			if x.CreatorID == creatorID && x.RequestID == requestID {
364				return x
365			}
366		}
367		return nil
368	}
369	
370	// sameExchangeRequest 判断重试参数是否与既有交换完全一致（记录集合顺序无关）。
371	func sameExchangeRequest(x *Exchange, patientID ID, receiverID, authorizationID ID, wantedRecordIDs []ID) bool {
372		if x.PatientID != patientID || x.ReceiverID != receiverID || x.AuthorizationID != authorizationID {
373			return false
374		}
375		if len(x.Package.Records) != len(wantedRecordIDs) {
376			return false
377		}
378		// 包内记录按记录标识排序保存，wantedRecordIDs 同样已去重排序。
379		for i, pr := range x.Package.Records {
380			if pr.RecordID != wantedRecordIDs[i] {
381				return false
382			}
383		}
384		return true
385	}
386	
387	func uniqueSortedIDs(ids []ID) []ID {
388		seen := make(map[ID]struct{}, len(ids))
389		out := make([]ID, 0, len(ids))
390		for _, id := range ids {
391			if _, ok := seen[id]; ok {
392				continue
393			}
394			seen[id] = struct{}{}
395			out = append(out, id)
396		}
397		sort.Strings(out)
398		return out
399	}
400	
401	func clonePackage(p Package) Package {
402		p.Records = append([]PackagedRecord(nil), p.Records...)
403		return p
404	}
405	
406	func cloneExchangeValue(x *Exchange) Exchange {
407		y := *x
408		y.Package = clonePackage(x.Package)
409		if x.Receipt != nil {
410			r := *x.Receipt
411			y.Receipt = &r
412		}
413		return y
414	}
415	
416	// canonicalRecord 固定摘要中每个字段的序列化顺序。
417	type canonicalRecord struct {
418		EncounterID ID     `json:"encounter_id"`
419		Category    string `json:"category"`
420		RecordID    ID     `json:"record_id"`
421		VersionID   ID     `json:"version_id"`
422		Version     int    `json:"version"`
423		EffectiveAt string `json:"effective_at"`
424		Content     string `json:"content"`
425	}
426	
427	type canonicalPackage struct {
428		PatientID  ID                `json:"patient_id"`
429		ReceiverID string            `json:"receiver_id"`
430		Records    []canonicalRecord `json:"records"`
431	}
432	
433	// packageDigest 计算包内容的稳定摘要：记录先按标识排序（创建时已排序），
434	// 时间统一为 UTC RFC3339Nano，字段顺序固定，因此与入参顺序无关、可重算核对。
435	func packageDigest(p Package) string {
436		cp := canonicalPackage{
437			PatientID:  p.PatientID,
438			ReceiverID: p.ReceiverID,
439			Records:    make([]canonicalRecord, 0, len(p.Records)),
440		}
441		recs := append([]PackagedRecord(nil), p.Records...)
442		sort.Slice(recs, func(i, j int) bool { return recs[i].RecordID < recs[j].RecordID })
443		for _, r := range recs {
444			cp.Records = append(cp.Records, canonicalRecord{
445				EncounterID: r.EncounterID,
446				Category:    r.Category,
447				RecordID:    r.RecordID,
448				VersionID:   r.VersionID,
449				Version:     r.Version,
450				EffectiveAt: r.EffectiveAt.UTC().Format(time.RFC3339Nano),
451				Content:     r.Content,
452			})
453		}
454		raw, err := json.Marshal(cp)
455		if err != nil {
456			// 参与序列化的都是字符串/整数等基础类型，不应失败。
457			panic(fmt.Errorf("clinical: cannot marshal package digest: %w", err))
458		}
459		sum := sha256.Sum256(raw)
460		return hex.EncodeToString(sum[:])
461	}
462

file.content:
package clinical

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"sort"
	"strings"
	"time"
)

// PackageDelivery 是指定接收方取包时得到的视图：交换标识、当前状态、
// 创建时间、包内容与摘要，不含内部使用者标识等包外信息。
type PackageDelivery struct {
	ExchangeID ID
	Status     string
	Digest     string
	CreatedAt  time.Time
	Package    Package
}

// ReceiptConfirmation 是接收方登记回执后得到的确认。
// 只含交换标识、当前状态、回执结果与登记时间，不含任何受保护内容；
// 授权失效或患者停用后登记回执也只返回该确认。
type ReceiptConfirmation struct {
	ExchangeID   ID
	Status       string
	Outcome      string
	RegisteredAt time.Time
}

// CreateExchange 由内部使用者把一条当前有效授权覆盖的已生效记录集合打包给
// 指定接收方。
//
// 参数：患者、接收方、绑定授权、记录标识集合与非空请求号。记录必须属于该
// 患者且已经生效；每条记录都必须被绑定的那一条授权覆盖——整类范围按记录的
// 就诊+类别覆盖，限定范围只覆盖明确选中的记录，不能借用同一接收方的其他
// 授权补足。授权必须属于该患者与接收方且在当前时间有效。空集合、空白请求号、
// 不存在或跨患者的引用、夹带草稿、记录不被绑定授权覆盖、授权不符一律拒绝，
// 不留下交换或审计，也不占用请求号。患者停用后不能新建交换。
//
// 成功后包内容固化为创建时各记录的当前生效版本（重复记录标识合并），并计算
// 稳定摘要，状态为待回执；交换与审计事件在同一次原子落盘中保留。此后记录被
// 更正或有新版本、新增记录都不会改写已创建的包。
//
// 请求号按发起的内部使用者区分：同一使用者以相同请求号携带相同患者、接收方、
// 授权与记录集合（顺序不限）重试时，返回原交换及其现有状态，不重新取内容、
// 不新增审计；其他参数变化返回 ErrConflict。首次失败不占用请求号。
// 命中已保存交换的重试只是读取既有结果、不产生任何状态变更，因此不再落盘：
// 即使本地保存条件当前不可用，重试也成功返回正式保存的那份交换。
func (s *Store) CreateExchange(actor Actor, patientID ID, receiverID, authorizationID ID, recordIDs []ID, requestID string) (Exchange, error) {
	if !actor.valid() || !actor.IsInternal() {
		return Exchange{}, ErrAccessDenied
	}
	if patientID == "" {
		return Exchange{}, fmt.Errorf("%w: patient id is required", ErrInvalidArgument)
	}
	if strings.TrimSpace(receiverID) == "" {
		return Exchange{}, fmt.Errorf("%w: receiver id is required", ErrInvalidArgument)
	}
	if strings.TrimSpace(authorizationID) == "" {
		return Exchange{}, fmt.Errorf("%w: authorization id is required", ErrInvalidArgument)
	}
	if strings.TrimSpace(requestID) == "" {
		return Exchange{}, fmt.Errorf("%w: request id is required", ErrInvalidArgument)
	}
	if len(recordIDs) == 0 {
		return Exchange{}, fmt.Errorf("%w: record id set must not be empty", ErrInvalidArgument)
	}
	for _, rid := range recordIDs {
		if strings.TrimSpace(rid) == "" {
			return Exchange{}, fmt.Errorf("%w: record id must not be blank", ErrInvalidArgument)
		}
	}
	wanted := uniqueSortedIDs(recordIDs)

	var result Exchange
	err := s.mutate(func(snap *snapshot) error {
		// 幂等检索优先：同一使用者的同一请求号无论当前患者/授权状态如何，
		// 都只返回原结果（重试不是新建）。
		if existing := findExchangeByRequest(snap, actor.ID, requestID); existing != nil {
			if !sameExchangeRequest(existing, patientID, receiverID, authorizationID, wanted) {
				return fmt.Errorf("%w: request id %q already used with different parameters", ErrConflict, requestID)
			}
			result = *existing
			if existing.Receipt != nil {
				r := *existing.Receipt
				result.Receipt = &r
			}
			result.Package.Records = append([]PackagedRecord(nil), existing.Package.Records...)
			// 命中已保存的交换：没有任何状态变更，不落盘——即使本地保存
			// 条件当前不可用，重试也必须成功返回原交换。
			return errUnchanged
		}

		// 首次创建：患者必须存在且未停用。
		if _, err := requireActivePatient(snap, patientID); err != nil {
			return err
		}

		// 绑定授权必须存在、属于该患者与接收方、当前有效。
		a := snap.Authorizations[authorizationID]
		if a == nil {
			return fmt.Errorf("%w: authorization %q", ErrNotFound, authorizationID)
		}
		if a.PatientID != patientID {
			return fmt.Errorf("%w: authorization %q belongs to patient %q, not %q",
				ErrMismatchedPatient, authorizationID, a.PatientID, patientID)
		}
		if a.ReceiverID != receiverID {
			return fmt.Errorf("%w: authorization %q is bound to receiver %q, not %q",
				ErrInvalidArgument, authorizationID, a.ReceiverID, receiverID)
		}
		now := s.now()
		if !a.ActiveAt(now) {
			// 未开始、已到期或已撤回：没有覆盖此次打包的有效授权。
			return fmt.Errorf("%w: authorization %q is not active", ErrAccessDenied, authorizationID)
		}

		// 逐记录固化当前生效版本；重复标识已合并，按记录标识排序保证确定性。
		pkg := Package{PatientID: patientID, ReceiverID: receiverID}
		for _, rid := range wanted {
			r := snap.Records[rid]
			if r == nil {
				return fmt.Errorf("%w: record %q", ErrNotFound, rid)
			}
			if r.PatientID != patientID {
				return fmt.Errorf("%w: record %q belongs to patient %q, not %q",
					ErrMismatchedPatient, rid, r.PatientID, patientID)
			}
			if r.CurrentVersionID == "" {
				return fmt.Errorf("%w: record %q has no effective version; activate its draft first",
					ErrInvalidArgument, rid)
			}
			v := snap.Versions[r.CurrentVersionID]
			if v == nil {
				return fmt.Errorf("%w: current version %q of record %q", ErrNotFound, r.CurrentVersionID, rid)
			}
			// 每条记录都必须被绑定授权自身覆盖：整类范围或限定范围。
			// 同一接收方的其他授权不能补足；夹带一条未覆盖记录即整包拒绝。
			if !authorizationCoversRecord(a, r) {
				return fmt.Errorf("%w: record %q (encounter %q, category %q) is not covered by authorization %q",
					ErrAccessDenied, rid, r.EncounterID, r.Category, authorizationID)
			}
			pkg.Records = append(pkg.Records, PackagedRecord{
				EncounterID: r.EncounterID,
				Category:    r.Category,
				RecordID:    r.ID,
				VersionID:   v.ID,
				Version:     v.Number,
				EffectiveAt: v.CreatedAt,
				Content:     v.Content,
			})
		}

		x := &Exchange{
			ID:              newID("exch"),
			PatientID:       patientID,
			ReceiverID:      receiverID,
			AuthorizationID: authorizationID,
			RequestID:       requestID,
			CreatorID:       actor.ID,
			Status:          ExchangePending,
			Digest:          packageDigest(pkg),
			Package:         pkg,
			CreatedAt:       now,
		}
		snap.Exchanges[x.ID] = x
		s.addAudit(snap, patientID, actor, ActionExchanged, "exchange", x.ID, now)
		result = *x
		result.Package.Records = append([]PackagedRecord(nil), x.Package.Records...)
		return nil
	})
	return result, err
}

// FetchPackage 供指定接收方凭交换标识取包。
//
// 每次取包都重新检查绑定授权与患者状态：授权必须仍是创建时绑定的那一条且
// 已开始、未到期、未撤回，患者档案必须未停用；其他有效授权不能替代绑定授权。
// 是否允许取包按“本次核对时间”判断：请求发出后若因等待同一存储上的其他操作
// 而排队，以等待结束、真正开始核对本次取包权限的时刻为准（进入临界区后才
// 取样，与接收方 Read 的时间含义一致），提前发出的请求不会延长授权有效期；
// 时间窗仍是半开区间 [开始, 截止)，恰好到达截止时刻即失效。授权未开始、
// 到期、撤回或患者停用后返回 ErrAccessDenied，交付结果为空，不返回包内容、
// 摘要、记录标识或交换状态。
// 其他接收方、内部使用者以及不存在的交换统一拒绝，不泄露交换是否存在。
//
// 成功时返回交换创建时固化的包及其摘要与当前状态；此后记录被更正也不会
// 重新打包，包内版本与内容仍以创建时保存的为准。
func (s *Store) FetchPackage(actor Actor, exchangeID ID) (PackageDelivery, error) {
	if !actor.valid() || actor.Kind != "receiver" {
		return PackageDelivery{}, ErrAccessDenied
	}
	if strings.TrimSpace(exchangeID) == "" {
		return PackageDelivery{}, fmt.Errorf("%w: exchange id is required", ErrInvalidArgument)
	}

	var out PackageDelivery
	err := s.view(func(snap *snapshot) error {
		// 核对时刻在进入临界区、真正开始核对本次取包权限时才取样：请求发出后
		// 若因等待其他操作而排队，等待时间不能延长绑定授权的有效判断——
		// 是否可取一律按这同一时刻判断，与 Read 的时间含义一致。
		now := s.now()
		x := snap.Exchanges[exchangeID]
		if x == nil || x.ReceiverID != actor.ID {
			// 不存在或属于其他接收方：统一拒绝，不泄露存在性。
			return ErrAccessDenied
		}
		p := snap.Patients[x.PatientID]
		if p == nil || p.Deactivated {
			return ErrAccessDenied
		}
		// 必须仍是绑定的那条授权（同一患者与接收方）；其他有效授权不能替代。
		a := snap.Authorizations[x.AuthorizationID]
		if a == nil || a.PatientID != x.PatientID || a.ReceiverID != actor.ID || !a.ActiveAt(now) {
			return ErrAccessDenied
		}
		out = PackageDelivery{
			ExchangeID: x.ID,
			Status:     x.Status,
			Digest:     x.Digest,
			CreatedAt:  x.CreatedAt,
			Package:    clonePackage(x.Package),
		}
		return nil
	})
	return out, err
}

// SubmitReceipt 供指定接收方对一份包登记回执：提供交换标识、取包时得到的
// 包摘要、接受或拒绝的结果及原因。
//
// 非法结果、拒绝时原因为空白返回 ErrInvalidArgument。只有指定接收方且摘要
// 吻合，才能把交换从待回执变为已接受或已拒绝；摘要不符返回 ErrConflict，
// 状态不变。相同回执（结果与原因均相同）重交返回原确认，不新增审计；结果
// 或原因改变返回 ErrConflict。其他身份不能代交，不存在的交换统一拒绝。
//
// 授权失效或患者停用后仍允许登记此前包的回执，但响应只返回确认状态，
// 不提供任何受保护内容。
func (s *Store) SubmitReceipt(actor Actor, exchangeID ID, digest, outcome, reason string) (ReceiptConfirmation, error) {
	if !actor.valid() || actor.Kind != "receiver" {
		return ReceiptConfirmation{}, ErrAccessDenied
	}
	if strings.TrimSpace(exchangeID) == "" {
		return ReceiptConfirmation{}, fmt.Errorf("%w: exchange id is required", ErrInvalidArgument)
	}
	if outcome != ReceiptAccepted && outcome != ReceiptRejected {
		return ReceiptConfirmation{}, fmt.Errorf("%w: outcome must be %q or %q", ErrInvalidArgument, ReceiptAccepted, ReceiptRejected)
	}
	if outcome == ReceiptRejected && strings.TrimSpace(reason) == "" {
		return ReceiptConfirmation{}, fmt.Errorf("%w: rejection reason is required", ErrInvalidArgument)
	}
	if outcome == ReceiptAccepted {
		// 接受不携带原因；统一归一化，保证重复提交判定稳定。
		reason = ""
	}

	var conf ReceiptConfirmation
	err := s.mutate(func(snap *snapshot) error {
		x := snap.Exchanges[exchangeID]
		if x == nil || x.ReceiverID != actor.ID {
			// 不存在或属于其他接收方/其他身份：统一拒绝。
			return ErrAccessDenied
		}
		if digest != x.Digest {
			return fmt.Errorf("%w: package digest does not match exchange %q", ErrConflict, exchangeID)
		}
		if x.Receipt != nil {
			if x.Receipt.Outcome != outcome || x.Receipt.Reason != reason {
				return fmt.Errorf("%w: exchange %q already has a different receipt", ErrConflict, exchangeID)
			}
			// 相同回执重交：返回原确认，不新增审计、不改状态。
			conf = ReceiptConfirmation{
				ExchangeID:   x.ID,
				Status:       x.Status,
				Outcome:      x.Receipt.Outcome,
				RegisteredAt: x.Receipt.RegisteredAt,
			}
			return nil
		}

		now := s.now()
		x.Receipt = &Receipt{Outcome: outcome, Reason: reason, RegisteredAt: now}
		if outcome == ReceiptAccepted {
			x.Status = ExchangeAccepted
		} else {
			x.Status = ExchangeRejected
		}
		s.addAudit(snap, x.PatientID, actor, ActionReceipted, "exchange", x.ID, now)
		conf = ReceiptConfirmation{
			ExchangeID:   x.ID,
			Status:       x.Status,
			Outcome:      outcome,
			RegisteredAt: now,
		}
		return nil
	})
	return conf, err
}

// GetExchange 供内部使用者按患者查看原包（含固化内容与摘要）及回执。
// 患者停用后仍可查看。交换不存在返回 ErrNotFound，属于其他患者返回
// ErrMismatchedPatient。
func (s *Store) GetExchange(actor Actor, patientID, exchangeID ID) (Exchange, error) {
	if !actor.valid() || !actor.IsInternal() {
		return Exchange{}, ErrAccessDenied
	}
	var result Exchange
	err := s.view(func(snap *snapshot) error {
		x, err := requireExchange(snap, patientID, exchangeID)
		if err != nil {
			return err
		}
		result = cloneExchangeValue(x)
		return nil
	})
	return result, err
}

// ListExchanges 供内部使用者按患者查看其全部交换（原包与回执），
// 按创建时间旧到新排序；时间戳相同时按交换标识排序。患者停用后仍可查看。
func (s *Store) ListExchanges(actor Actor, patientID ID) ([]Exchange, error) {
	if !actor.valid() || !actor.IsInternal() {
		return nil, ErrAccessDenied
	}
	var result []Exchange
	err := s.view(func(snap *snapshot) error {
		if _, err := requirePatient(snap, patientID); err != nil {
			return err
		}
		for _, x := range snap.Exchanges {
			if x.PatientID == patientID {
				result = append(result, cloneExchangeValue(x))
			}
		}
		sort.Slice(result, func(i, j int) bool {
			if !result[i].CreatedAt.Equal(result[j].CreatedAt) {
				return result[i].CreatedAt.Before(result[j].CreatedAt)
			}
			return result[i].ID < result[j].ID
		})
		return nil
	})
	return result, err
}

func requireExchange(snap *snapshot, patientID, exchangeID ID) (*Exchange, error) {
	x := snap.Exchanges[exchangeID]
	if x == nil {
		return nil, fmt.Errorf("%w: exchange %q", ErrNotFound, exchangeID)
	}
	if x.PatientID != patientID {
		return nil, fmt.Errorf("%w: exchange %q belongs to patient %q, not %q",
			ErrMismatchedPatient, exchangeID, x.PatientID, patientID)
	}
	return x, nil
}

func findExchangeByRequest(snap *snapshot, creatorID, requestID string) *Exchange {
	for _, x := range snap.Exchanges {
		if x.CreatorID == creatorID && x.RequestID == requestID {
			return x
		}
	}
	return nil
}

// sameExchangeRequest 判断重试参数是否与既有交换完全一致（记录集合顺序无关）。
func sameExchangeRequest(x *Exchange, patientID ID, receiverID, authorizationID ID, wantedRecordIDs []ID) bool {
	if x.PatientID != patientID || x.ReceiverID != receiverID || x.AuthorizationID != authorizationID {
		return false
	}
	if len(x.Package.Records) != len(wantedRecordIDs) {
		return false
	}
	// 包内记录按记录标识排序保存，wantedRecordIDs 同样已去重排序。
	for i, pr := range x.Package.Records {
		if pr.RecordID != wantedRecordIDs[i] {
			return false
		}
	}
	return true
}

func uniqueSortedIDs(ids []ID) []ID {
	seen := make(map[ID]struct{}, len(ids))
	out := make([]ID, 0, len(ids))
	for _, id := range ids {
		if _, ok := seen[id]; ok {
			continue
		}
		seen[id] = struct{}{}
		out = append(out, id)
	}
	sort.Strings(out)
	return out
}

func clonePackage(p Package) Package {
	p.Records = append([]PackagedRecord(nil), p.Records...)
	return p
}

func cloneExchangeValue(x *Exchange) Exchange {
	y := *x
	y.Package = clonePackage(x.Package)
	if x.Receipt != nil {
		r := *x.Receipt
		y.Receipt = &r
	}
	return y
}

// canonicalRecord 固定摘要中每个字段的序列化顺序。
type canonicalRecord struct {
	EncounterID ID     `json:"encounter_id"`
	Category    string `json:"category"`
	RecordID    ID     `json:"record_id"`
	VersionID   ID     `json:"version_id"`
	Version     int    `json:"version"`
	EffectiveAt string `json:"effective_at"`
	Content     string `json:"content"`
}

type canonicalPackage struct {
	PatientID  ID                `json:"patient_id"`
	ReceiverID string            `json:"receiver_id"`
	Records    []canonicalRecord `json:"records"`
}

// packageDigest 计算包内容的稳定摘要：记录先按标识排序（创建时已排序），
// 时间统一为 UTC RFC3339Nano，字段顺序固定，因此与入参顺序无关、可重算核对。
func packageDigest(p Package) string {
	cp := canonicalPackage{
		PatientID:  p.PatientID,
		ReceiverID: p.ReceiverID,
		Records:    make([]canonicalRecord, 0, len(p.Records)),
	}
	recs := append([]PackagedRecord(nil), p.Records...)
	sort.Slice(recs, func(i, j int) bool { return recs[i].RecordID < recs[j].RecordID })
	for _, r := range recs {
		cp.Records = append(cp.Records, canonicalRecord{
			EncounterID: r.EncounterID,
			Category:    r.Category,
			RecordID:    r.RecordID,
			VersionID:   r.VersionID,
			Version:     r.Version,
			EffectiveAt: r.EffectiveAt.UTC().Format(time.RFC3339Nano),
			Content:     r.Content,
		})
	}
	raw, err := json.Marshal(cp)
	if err != nil {
		// 参与序列化的都是字符串/整数等基础类型，不应失败。
		panic(fmt.Errorf("clinical: cannot marshal package digest: %w", err))
	}
	sum := sha256.Sum256(raw)
	return hex.EncodeToString(sum[:])
}

