177		if err := s.Close(); err != nil {
178			t.Fatal(err)
179		}
180		if err := os.Remove(dataPath); err != nil {
181			t.Fatalf("unblock data path: %v", err)
182		}
183		if err := os.Rename(backupPath, dataPath); err != nil {
184			t.Fatalf("restore data file: %v", err)
185		}
186	
187		s2 := open()
188		t.Cleanup(func() { _ = s2.Close() })
189		// 重开后仍是提交前的正式数据：失败尝试没有变成回执或事件。
190		checkIntact("after reopen", s2)
191	
192		// 保存条件恢复后：同一接收方对同一份交换、以与失败尝试不同的非空原因
193		// 重新登记。失败尝试没有建立回执，不得返回已有回执冲突。
194		clk.t = clk.t.Add(time.Hour)
195		succeededAt := clk.t
196		if succeededAt.Equal(failedAttemptAt) {
197			t.Fatal("test clock must distinguish failed attempt from successful registration")
198		}
199		conf, err := s2.SubmitReceipt(rcv, x.ID, x.Digest, ReceiptRejected, "重试成功的拒绝原因")
200		if err != nil {
201			t.Fatalf("retry with a different reason after recovery: %v", err)
202		}
203		if conf.ExchangeID != x.ID || conf.Status != ExchangeRejected || conf.Outcome != ReceiptRejected {
204			t.Fatalf("bad confirmation: %+v", conf)
205		}
206		// 登记时间采用成功登记时的时间，而不是失败尝试的时间。
207		if !conf.RegisteredAt.Equal(succeededAt) {
208			t.Fatalf("registered at %v != successful attempt time %v (failed attempt was %v)",
