278		clk.t = clk.t.Add(time.Hour)
279		if _, err := s2.SubmitReceipt(rcv, x.ID, x.Digest, ReceiptRejected, "试图覆盖的拒绝原因"); !errors.Is(err, ErrConflict) {
280			t.Fatalf("overwrite attempt err = %v, want ErrConflict", err)
281		}
282		got, err = s2.GetExchange(doc, p.ID, x.ID)
283		if err != nil {
284			t.Fatal(err)
285		}
286		assertExchangeMatches(t, got, want, "exchange after overwrite attempt")
287		if audit2 := mustAudit(t, s2, p.ID); !reflect.DeepEqual(audit2, audit) {
